p1.etc/license-cache/118/clients.json:
{
  "client_group": "cloud-gateways",
  "peers": ["gw-lumen-east", "gw-lumen-west", "gw-meridian-1", "gw-meridian-2", "gw-cascade-1", "gw-sable-1"],
  "renewal_windows": {
    "interval_s": 21600,
    "window_s": 1800,
    "synchronized": true,
    "opens_utc": ["00:00", "06:00", "12:00", "18:00"]
  },
  "route": {"device": 118, "service": "license-cache-118"},
  "notes": "All six peers renew inside the same 30-minute windows. Between windows the daemon sees no renewal requests."
}

